                if u != first and u != last:
                    ent[0] -= 1
                if v != first and v != last:
                    ent[1] -= 1

    for path, count in entries:
        pid = len(paths)
        paths.append(path)
        counts.append(count)
        alive.append(True)
        apply_path(path, pid, True)

    rounds = {}
    rnd = 0
    while True:
        rnd += 1
        marked = set()
        for key in pending:
            if link_cnt.get(key, 0) > 0:
                ent = block[key]
                if ent[0] == 0 or ent[1] == 0:
                    marked.add(key)
        pending = set()
        if not marked:
            break
        for key in marked:
            rounds[key] = rnd
        affected = set()
        for key in marked:
            affected.update(containing[key])
        for pid in affected:
            p = paths[pid]
            apply_path(p, pid, False)
            fl = _canon(p[0], p[1])
            ll = _canon(p[-2], p[-1])
            start = 1 if fl in marked else 0
            stop = len(p) - 1 if ll in marked else len(p)
            q = p[start:stop]
            if len(q) >= 2:
                paths[pid] = q
                apply_path(q, pid, True)
            else:
                alive[pid] = False

    final = {}
    for pid in range(len(paths)):
        if alive[pid]:
            key = paths[pid]
            final[key] = final.get(key, 0) + counts[pid]
    return final, rounds


